//! 🔺️ reorder-skins leaf-owned typed sparse operation diff.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfSkin;
use crate::artifacts::gltf::schema::diff::GltfDiff;
use crate::artifacts::gltf::schema::mutations::reorder_skins::mutation::{apply, validate, GltfReorderSkinsPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{skins_op, family_diff, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.reorder-skins.v1";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfReorderSkinsOperation { Insert { position: usize, item: GltfSkin }, Delete { index: usize, removed: GltfSkin }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfReorderSkinsDiff { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfReorderSkinsPayload, pub operation: GltfReorderSkinsOperation }
async fn operation(payload: &GltfReorderSkinsPayload, base: &GltfSnapshot) -> GltfReorderSkinsOperation { GltfReorderSkinsOperation::Reorder { order: payload.order.clone() } }
async fn touched_paths(payload: &GltfReorderSkinsPayload) -> Vec<String> { payload.order.iter().map(|index| format!("document/skins/{}", index)).chain(std::iter::empty()).collect() }
pub async fn validate_diff(diff: &GltfReorderSkinsDiff, base: &GltfSnapshot) -> Result<(), GltfTopLevelMutationRejection> { if diff.id != ID || diff.version != 1 { return Err(reject("gltf.mutation.invalid-diff-envelope", "diff", "descriptor identity does not match")); } if diff.touched_paths != touched_paths(&diff.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "diff/touchedPaths", "paths must be concrete payload-derived locations")); } validate(&diff.payload, base)?; if diff.operation != operation(&diff.payload, base) { return Err(reject("gltf.mutation.invalid-sparse-operation", "diff/operation", "operation must equal the direct typed delta")); } Ok(()) }
pub async fn apply_diff(diff: &GltfReorderSkinsDiff, base: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_diff(diff, base)?; let mut next = base.clone(); let operation = &diff.operation; match operation { GltfReorderSkinsOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Skins, &Change::Insert(*position))?; next.document.skins.insert(*position, item.clone());  }, GltfReorderSkinsOperation::Delete { index, .. } => { skins_op(&mut next, GltfTopLevelFamily::Skins, *index, None, None)?;  }, GltfReorderSkinsOperation::Move { index, position } => { skins_op(&mut next, GltfTopLevelFamily::Skins, *index, Some(*position), None)?;  }, GltfReorderSkinsOperation::Reorder { order } => { skins_op(&mut next, GltfTopLevelFamily::Skins, order[0], None, Some(order))?;  } } Ok(next) }
pub async fn encode(diff: &GltfReorderSkinsDiff) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(diff).map_err(|error| reject("gltf.mutation.encode-failed", "diff", error.to_string())) }
pub async fn derive(payload: &GltfReorderSkinsPayload, base: &GltfSnapshot) -> Result<GltfReorderSkinsDiff, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfReorderSkinsDiff { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
pub async fn derive_transitional_gltf_diff(payload: &GltfReorderSkinsPayload, base: &GltfSnapshot) -> Result<GltfDiff, GltfTopLevelMutationRejection> { let next = apply(payload, base)?; Ok(family_diff(GltfTopLevelFamily::Skins, base, &next)) }
